use crate::sign::Sign;
use crate::wide::I256;

use super::{decide, larger, largest_magnitude, rounded_f64, within};

/// The filter's error constant: E · (1 + 2u)^2 with E = 14u + 10u^2 + 2u^3, the result's unit error
/// (header), rounded up to an `f64`: 7881299347898373 · 2^-102.
const ERROR: f64 = f64::from_bits(0x3cdc_0000_0000_0005);

/// `carrier_side`'s sign from its `f64` filter, or `None` when the filter's bound cannot certify
/// it.
///
/// `Some(Sign::Zero)` only when the scale is zero, which makes the exact value zero; `None` also
/// for a rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn filter(a: i128, b: i128, c: i128, x: i128, y: i128, w: i128) -> Option<Sign> {
    let a = rounded_f64(a, 41)?;
    let x = rounded_f64(x, 124)?;
    let s_1 = a * x;
    let b = rounded_f64(b, 41)?;
    let y = rounded_f64(y, 124)?;
    let s_2 = b * y;
    let s_3 = s_1 + s_2;
    let c = rounded_f64(c, 82)?;
    let w = rounded_f64(w, 83)?;
    let s_4 = c * w;
    let s = s_3 - s_4;
    let m_n = largest_magnitude([a, b]);
    let m_d = largest_magnitude([c]);
    let m_p = largest_magnitude([x, y]);
    let m_w = largest_magnitude([w]);
    let scale = larger(m_d * m_w, m_n * m_p);
    decide(s, ERROR, scale)
}

/// `carrier_side`'s exact value: each step in the type its certificate gives it, with checked
/// arithmetic; `None` only if a step overflowed, which the certificate rules out; `None` also for a
/// rounded input outside its declared range.
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    clippy::similar_names,
    reason = "names, parameters and lines follow the description: one per input and step"
)]
pub fn value(a: i128, b: i128, c: i128, x: i128, y: i128, w: i128) -> Option<I256> {
    let a = i64::try_from(within(a, 41)?).ok()?;
    let x = within(x, 124)?;
    let s_1 = I256::product_i128(i128::from(a), x)?;
    let b = i64::try_from(within(b, 41)?).ok()?;
    let y = within(y, 124)?;
    let s_2 = I256::product_i128(i128::from(b), y)?;
    let s_3 = s_1.checked_add(&s_2)?;
    let c = within(c, 82)?;
    let w = within(w, 83)?;
    let s_4 = I256::product_i128(c, w)?;
    let s = s_3.checked_sub(&s_4)?;
    Some(s)
}

/// `carrier_side`'s exact sign: the sign of [`value`], or `None` as for [`value`].
#[inline]
#[must_use]
#[allow(
    clippy::many_single_char_names,
    reason = "one-letter names are the description's points"
)]
pub fn exact(a: i128, b: i128, c: i128, x: i128, y: i128, w: i128) -> Option<Sign> {
    value(a, b, c, x, y, w).map(|v| v.signum())
}
